INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-001', 'exam-fe', 'ネットワーク', 'standard', 'single_choice', '【知学オリジナル・科目A 演習1】IPv4 のネットワーク 192.168.40.0/27 で，ネットワークアドレスとブロードキャストアドレスを除いて通常割り当て可能なホストアドレス数は幾つか。', '[{"id":"a","text":"14"},{"id":"b","text":"30"},{"id":"c","text":"31"},{"id":"d","text":"32"}]', '"b"', '/27 のホスト部は 5 ビットなので全32アドレス。ネットワークとブロードキャストを除き30個。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-002', 'exam-fe', 'ネットワーク', 'standard', 'single_choice', '【知学オリジナル・科目A 演習2】192.168.8.0/24 を同じ大きさの /26 ネットワークに分割すると，サブネットは幾つできるか。', '[{"id":"a","text":"2"},{"id":"b","text":"4"},{"id":"c","text":"6"},{"id":"d","text":"8"}]', '"b"', '/24 から /26 へ借りるネットワーク部は2ビット。2²=4個。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-003', 'exam-fe', 'コンピュータ構成', 'standard', 'single_choice', '【知学オリジナル・科目A 演習3】キャッシュヒット率が90％，キャッシュアクセス4ns，ミス時は主記憶80nsだけを参照するとき，平均アクセス時間は幾らか。ミス時の追加キャッシュ時間は考慮しない。', '[{"id":"a","text":"7.6ns"},{"id":"b","text":"11.6ns"},{"id":"c","text":"40ns"},{"id":"d","text":"76.4ns"}]', '"b"', '0.9×4＋0.1×80＝11.6ns。ミス時の条件を明示した加重平均。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-004', 'exam-fe', 'ストレージ', 'standard', 'single_choice', '【知学オリジナル・科目A 演習4】二つのディスクに同一データを書き込み，一方が故障しても残るディスクで継続できる RAID の方式はどれか。', '[{"id":"a","text":"RAID 0"},{"id":"b","text":"RAID 1"},{"id":"c","text":"ストライピングのみ"},{"id":"d","text":"単一ディスク"}]', '"b"', 'RAID 1 はミラーリング。RAID 0 のストライピングだけでは冗長性を持たない。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-005', 'exam-fe', 'データベース', 'standard', 'single_choice', '【知学オリジナル・科目A 演習5】二つのトランザクションが同時に処理されても，互いの途中結果の影響を受けないようにする ACID 特性はどれか。', '[{"id":"a","text":"原子性"},{"id":"b","text":"一貫性"},{"id":"c","text":"独立性"},{"id":"d","text":"耐久性"}]', '"c"', '独立性（分離性）は並行トランザクション間の干渉を防ぐ。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-006', 'exam-fe', 'SQL・データベース', 'standard', 'single_choice', '【知学オリジナル・科目A 演習6】注文表（顧客ID，金額）で，顧客ごとの注文件数が3件以上の顧客IDだけを取得したい。正しい SQL はどれか。', '[{"id":"a","text":"SELECT 顧客ID FROM 注文 WHERE COUNT(*) >= 3 GROUP BY 顧客ID"},{"id":"b","text":"SELECT 顧客ID FROM 注文 GROUP BY 顧客ID HAVING COUNT(*) >= 3"},{"id":"c","text":"SELECT 顧客ID FROM 注文 ORDER BY COUNT(*) >= 3"},{"id":"d","text":"SELECT 顧客ID FROM 注文 HAVING 金額 >= 3"}]', '"b"', '集約結果に条件を付けるのは HAVING。WHERE ではグループ集約関数を直接指定しない。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-007', 'exam-fe', 'SQL・データベース', 'standard', 'single_choice', '【知学オリジナル・科目A 演習7】社員表のすべての行を残し，所属部署が見つからない社員の部署名は NULL として結果を得る結合はどれか。', '[{"id":"a","text":"INNER JOIN"},{"id":"b","text":"CROSS JOIN"},{"id":"c","text":"LEFT OUTER JOIN"},{"id":"d","text":"NATURAL JOIN のみ"}]', '"c"', '左外部結合は左側の社員表をすべて保持し，対応する部署がない場合は部署側をNULLにする。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-008', 'exam-fe', 'データ構造', 'standard', 'single_choice', '【知学オリジナル・科目A 演習8】容量200のハッシュ表に120要素が格納されている。負荷率は幾らか。', '[{"id":"a","text":"0.40"},{"id":"b","text":"0.60"},{"id":"c","text":"0.80"},{"id":"d","text":"1.20"}]', '"b"', '負荷率は格納要素数／表容量＝120／200＝0.60。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-009', 'exam-fe', 'アルゴリズム', 'standard', 'single_choice', '【知学オリジナル・科目A 演習9】すでに昇順に整列した長さ1024の配列を二分探索する場合，最大比較回数のおおよそのオーダーはどれか。', '[{"id":"a","text":"O(1)"},{"id":"b","text":"O(log n)"},{"id":"c","text":"O(n)"},{"id":"d","text":"O(n²)"}]', '"b"', '探索範囲を毎回半分にできるため時間計算量はO(log n)。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-010', 'exam-fe', 'ネットワーク', 'standard', 'single_choice', '【知学オリジナル・科目A 演習10】HTTP の状態コード 429 が表す内容として，最も適切なものはどれか。', '[{"id":"a","text":"認証されていない"},{"id":"b","text":"アクセス回数が多すぎる"},{"id":"c","text":"要求した資源が存在しない"},{"id":"d","text":"サーバ内で致命的なエラーが発生した"}]', '"b"', '429 Too Many Requests はレート制限などで短時間の要求が多すぎる状態。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-011', 'exam-fe', 'ネットワーク', 'standard', 'single_choice', '【知学オリジナル・科目A 演習11】DNS の TTL を短くすることの一般的な影響はどれか。', '[{"id":"a","text":"キャッシュの有効期限が短くなり変更が反映されやすい"},{"id":"b","text":"DNS 問い合わせが不要になる"},{"id":"c","text":"ドメイン名が暗号化される"},{"id":"d","text":"通信の遅延が必ずゼロになる"}]', '"a"', 'TTLが短いほど古い解決結果のキャッシュ期間が短くなる一方，DNS問い合わせ回数が増え得る。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-012', 'exam-fe', '情報セキュリティ', 'standard', 'single_choice', '【知学オリジナル・科目A 演習12】HTTPS サイトのサーバ証明書を検証する主目的はどれか。', '[{"id":"a","text":"接続先サーバの正当性確認"},{"id":"b","text":"端末内のウイルス駆除"},{"id":"c","text":"パスワードの強度判定"},{"id":"d","text":"ファイルの圧縮"}]', '"a"', '証明書チェーンやホスト名の確認を通じ，意図したサーバとのTLS接続か検証する。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-013', 'exam-fe', '情報セキュリティ', 'standard', 'single_choice', '【知学オリジナル・科目A 演習13】OAuth 2.0 のアクセストークンで利用権限の範囲を表す概念はどれか。', '[{"id":"a","text":"TTL"},{"id":"b","text":"スコープ"},{"id":"c","text":"ソルト"},{"id":"d","text":"リプレイ"}]', '"b"', 'scope はAPIアクセスなどに許された操作や資源の範囲を表す。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-014', 'exam-fe', '情報セキュリティ', 'standard', 'single_choice', '【知学オリジナル・科目A 演習14】ブラウザからの不正な他サイト経由の更新要求（CSRF）に対する代表的な防御策はどれか。', '[{"id":"a","text":"更新系リクエストで予測困難なCSRFトークンを検証する"},{"id":"b","text":"HTML全体を常に大文字にする"},{"id":"c","text":"HTTPを使用してTLSを無効にする"},{"id":"d","text":"すべてのCookieを永続化する"}]', '"a"', '正当なページに発行したCSRFトークンをサーバで検証する対策が有効。SameSite属性なども補助となる。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-015', 'exam-fe', '情報セキュリティ', 'standard', 'single_choice', '【知学オリジナル・科目A 演習15】利用者の投稿内容をエスケープせずにHTMLとして表示した結果，後から閲覧した別の利用者のブラウザで攻撃用スクリプトが動く。この攻撃はどれか。', '[{"id":"a","text":"SQLインジェクション"},{"id":"b","text":"格納型XSS"},{"id":"c","text":"総当たり攻撃"},{"id":"d","text":"DNSキャッシュポイズニング"}]', '"b"', '悪意ある入力がサーバに保存され，閲覧時に実行されるのは格納型クロスサイトスクリプティング。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-016', 'exam-fe', '情報セキュリティ', 'standard', 'single_choice', '【知学オリジナル・科目A 演習16】TOTP方式のワンタイムパスワードが，正しい秘密鍵を使っていても検証に失敗する原因としてあり得るものはどれか。', '[{"id":"a","text":"認証装置同士の時計のずれ"},{"id":"b","text":"端末画面が暗いこと"},{"id":"c","text":"通信のMTUが1500であること"},{"id":"d","text":"ファイル名が日本語であること"}]', '"a"', 'TOTPは時刻を入力に使うため端末・サーバの時刻差が許容窓を超えると失敗する。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-017', 'exam-fe', '情報セキュリティ', 'standard', 'single_choice', '【知学オリジナル・科目A 演習17】デジタル署名を検証する際，通常，署名者の秘密鍵と公開鍵のどちらを使うか。', '[{"id":"a","text":"秘密鍵"},{"id":"b","text":"公開鍵"},{"id":"c","text":"双方の秘密鍵"},{"id":"d","text":"共通鍵のみ"}]', '"b"', '署名は秘密鍵で生成し，対応する公開鍵で検証する。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-018', 'exam-fe', 'クラウド', 'standard', 'single_choice', '【知学オリジナル・科目A 演習18】PaaS の代表的な特徴はどれか。', '[{"id":"a","text":"サーバ筐体を利用者が必ず購入する"},{"id":"b","text":"アプリの実行基盤は提供側が用意し，利用者は主にアプリを開発・運用する"},{"id":"c","text":"利用者はOSカーネルを必ず管理する"},{"id":"d","text":"提供側が利用者固有の業務処理まですべて作成する"}]', '"b"', 'PaaSはOS・ミドルウェア等の基盤を提供し，利用者はアプリケーションを中心に開発・管理する。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-019', 'exam-fe', 'クラウド', 'standard', 'single_choice', '【知学オリジナル・科目A 演習19】コンテナイメージのレイヤを再利用する主な利点はどれか。', '[{"id":"a","text":"毎回すべてのファイルをゼロから転送する"},{"id":"b","text":"共通レイヤのキャッシュによってビルドや配布を効率化する"},{"id":"c","text":"すべてのコンテナが同じIPアドレスになる"},{"id":"d","text":"OSアップデートが一切不要になる"}]', '"b"', '変更のない共通レイヤを共有・再利用でき，ビルド時間や転送量を節約できる。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-020', 'exam-fe', 'ソフトウェア開発', 'standard', 'single_choice', '【知学オリジナル・科目A 演習20】テスト自動化を開発の初期段階から実施する「シフトレフト」の狙いはどれか。', '[{"id":"a","text":"問題の発見を後工程に集中させる"},{"id":"b","text":"欠陥を早期に発見して修正コストを下げる"},{"id":"c","text":"品質保証を完全に廃止する"},{"id":"d","text":"本番稼働後だけテストを行う"}]', '"b"', '検証工程を早い段階へ移し，問題を早期に見つけることで手戻りを減らす。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-021', 'exam-fe', 'プロジェクト管理', 'standard', 'single_choice', '【知学オリジナル・科目A 演習21】ある作業の出来高（EV）が80万円，実コスト（AC）が100万円だった。コスト効率指数CPIはどれか。', '[{"id":"a","text":"0.8"},{"id":"b","text":"1.0"},{"id":"c","text":"1.25"},{"id":"d","text":"1.8"}]', '"a"', 'CPI=EV÷AC=80÷100=0.8。1未満は費用効率が低い状態。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-022', 'exam-fe', 'プロジェクト管理', 'standard', 'single_choice', '【知学オリジナル・科目A 演習22】作業経路 A→C→E の所要時間が3,5,2日，B→D→E が4,6,2日のとき，プロジェクト全体の最短終了日数は幾つか。', '[{"id":"a","text":"10日"},{"id":"b","text":"11日"},{"id":"c","text":"12日"},{"id":"d","text":"14日"}]', '"c"', '各経路は10日と12日。最長経路（クリティカルパス）が全体所要日数12日を決める。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-023', 'exam-fe', '経営・損益分析', 'standard', 'single_choice', '【知学オリジナル・科目A 演習23】固定費が毎月120,000円，商品1個の売価500円，変動費200円のとき，損益分岐点販売数量は幾つか。', '[{"id":"a","text":"240個"},{"id":"b","text":"300個"},{"id":"c","text":"400個"},{"id":"d","text":"600個"}]', '"c"', '限界利益は500−200=300円／個。固定費120,000÷300=400個。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
INSERT OR IGNORE INTO questions (id, track_id, topic, difficulty, question_type, prompt, options_json, answer_json, explanation, source_type, source_reference, language, exam_section, exam_section_method) VALUES ('fe-original-v2-a-024', 'exam-fe', '品質管理', 'standard', 'single_choice', '【知学オリジナル・科目A 演習24】不具合件数を原因別に多い順から並べて累積比率を示し，重点改善項目を選ぶ際に使う図はどれか。', '[{"id":"a","text":"パレート図"},{"id":"b","text":"状態遷移図"},{"id":"c","text":"ガントチャート"},{"id":"d","text":"シーケンス図"}]', '"a"', 'パレート図は件数の降順棒グラフと累積構成比の折れ線で重点要因を可視化する。', 'generated', '知学オリジナル練習問題（IPA公式過去問ではありません）', 'ja', 'A', 'explicit');
